import React from 'react';

const Navigation = ({ links, onNavClick }) => {
  return (
    <nav className="hidden lg:flex items-center space-x-8">
      {links.map((link) => (
        link.path.startsWith('tel:') ? (
          <a
            key={link.name}
            href={link.path}
            className="text-white hover:text-[#5dade2] transition-colors text-sm font-medium tracking-wide"
          >
            {link.name}
          </a>
        ) : (
          <a
            key={link.name}
            href={link.path}
            onClick={(e) => onNavClick(e, link.path)}
            className="text-white hover:text-[#5dade2] transition-colors text-sm font-medium tracking-wide"
          >
            {link.name}
          </a>
        )
      ))}
    </nav>
  );
};

export default Navigation;
